class FeedPage extends StatefulWidget {
  const FeedPage({super.key});

  @override
  State<FeedPage> createState() => _FeedPageState();
}

class _FeedPageState extends State<FeedPage> with RouteAware {
  Timer? _poll;

  @override
  void initState() {
    super.initState();
    _start();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // needs a context inside the route, so not initState
    routeObserver.subscribe(this, ModalRoute.of(context)!);
  }

  void _start() =>
      _poll ??= Timer.periodic(const Duration(seconds: 5), (_) => _refresh());

  void _stop() {
    _poll?.cancel();
    _poll = null;
  }

  @override
  void didPushNext() => _stop();   // another route covered us
  @override
  void didPopNext() => _start();   // we are on top again

  @override
  void dispose() {                 // runs only when THIS route is popped
    _stop();
    routeObserver.unsubscribe(this);
    super.dispose();
  }

  void _refresh() {}

  @override
  Widget build(BuildContext context) => const Placeholder();
}

