class _CartState extends State<Cart> with RestorationMixin {
  final _note = RestorableTextEditingController();
  final _quantity = RestorableInt(1);

  @override
  String? get restorationId => 'cart';   // unique inside its scope

  @override
  void restoreState(RestorationBucket? oldBucket, bool initialRestore) {
    // values come back here after a process kill, before the first build
    registerForRestoration(_note, 'note');
    registerForRestoration(_quantity, 'qty');
  }

  @override
  void dispose() {
    _note.dispose();
    _quantity.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
        children: [
          TextField(controller: _note.value),
          Text('${_quantity.value}'),
          TextButton(
            onPressed: () => setState(() => _quantity.value++),
            child: const Text('+'),
          ),
        ],
      );
}

// Routes come back only if they were pushed restorably
void openDetails(BuildContext context) {
  Navigator.restorablePushNamed(context, '/details');  // plain push is not restored
}

